        {#each dataStore.tasks as task}
          <li>{task.text}</li>
        {/each}
      </ul>
    {/if}
  </section>
</div>

<style>
  .data-panel {
    font-family: sans-serif;
    padding: 0.75rem;
  }
  .panel-section {
